      sAccum1 += amzTexture(2, uv - dir * (amzp_streakLength * 0.18)).rgb * 0.35;
      sAccum1 += amzTexture(2, uv - dir * (amzp_streakLength * 0.42)).rgb * 0.18;
      sAccum1 *= 0.8;

      float angP = 0.523599;
      float2 rdirP = float2(cos(atan(dir.y,dir.x) + angP), sin(atan(dir.y,dir.x) + angP));
      float2 rdirM = float2(cos(atan(dir.y,dir.x) - angP), sin(atan(dir.y,dir.x) - angP));

      float3 sAccum2 = amzTexture(2, uv + rdirP * (amzp_streakLength * 0.08)).rgb * 0.55;
      sAccum2 += amzTexture(2, uv + rdirP * (amzp_streakLength * 0.24)).rgb * 0.3;
      sAccum2 *= 0.7;

