      float3 streaksCol = (sAccum0 * useS0 + sAccum1 * useS1 + sAccum2 * useS2 + sAccum3 * useS3);
      float3 streakTint = amzp_flareColor.rgb * (amzp_flareIntensity * 0.5);
      streaksCol = streaksCol * streakTint;


      float ring = smoothstep(0.02, 0.0, abs(dist - R*0.18)) * 0.6;
      float3 ringCol = amzp_flareColor.rgb * ring * (amzp_flareIntensity * 0.8);


      float sCnt = clamp(amzp_shapeCount, 0.0, 4.0);
      float useSh0 = step(0.5, sCnt);
      float useSh1 = step(1.5, sCnt);
      float useSh2 = step(2.5, sCnt);
      float useSh3 = step(3.5, sCnt);


      float baseAng = atan(st.y, st.x);


      float spreadRad = radians(amzp_shapeSpread);

      float a0 = baseAng + (-spreadRad);
      float a1 = baseAng + (-spreadRad * 0.333);
      float a2 = baseAng + ( spreadRad * 0.333);
      float a3 = baseAng + ( spreadRad);

      float2 shDir0 = normalize(float2(cos(a0), sin(a0)));
      float2 shDir1 = normalize(float2(cos(a1), sin(a1)));
      float2 shDir2 = normalize(float2(cos(a2), sin(a2)));
      float2 shDir3 = normalize(float2(cos(a3), sin(a3)));

      float sh0 = shapeMaskForDir(uv, center, shDir0, amzp_shapeDist, amzp_shapeSize, amzp_shapeSharp) * useSh0;
      float sh1 = shapeMaskForDir(uv, center, shDir1, amzp_shapeDist, amzp_shapeSize, amzp_shapeSharp) * useSh1;
      float sh2 = shapeMaskForDir(uv, center, shDir2, amzp_shapeDist, amzp_shapeSize, amzp_shapeSharp) * useSh2;
      float sh3 = shapeMaskForDir(uv, center, shDir3, amzp_shapeDist, amzp_shapeSize, amzp_shapeSharp) * useSh3;

      float shapesMask = clamp(sh0 + sh1 + sh2 + sh3, 0.0, 1.0);
      float3 shapesCol = amzp_shapeColor.rgb * shapesMask * amzp_shapeOpacity * amzp_flareIntensity;


      float3 glow = coreCol + barCol + ghost1 + ghost2 + ghost3 + streaksCol * 0.95 + amzp_haze * hazeMask + ringCol + shapesCol;


      float rad = amzp_hue * 0.017453292519943295;
      float3x3 huemat = float3x3(
        1.0, 0.0,       0.0,
        0.0, cos(rad),  sin(rad),
        0.0, -sin(rad), cos(rad)
      );
      float3 yuvCol = rgb2yuv * glow;
      yuvCol = yuvCol * huemat;
      float3 glowHue = yuv2rgb * yuvCol;


      float3 outCol;
      if(int(amzp_bmode) == 0){
        outCol = 1.0 - ((1.0 - src.rgb) * (1.0 - glowHue));
      } else if(int(amzp_bmode) == 1){
        outCol = src.rgb + glowHue;
      } else if(int(amzp_bmode) == 2){
        outCol = glowHue;
      } else {
        outCol = mix(src.rgb, glowHue, 0.5);
      }

      float s = clamp(amzp_strength, 0.0, 3.0);
      float3 finalCol = mix(src.rgb, outCol, s);

      if((amzp_GCE>0.5)){
        finalCol = pow(clamp(finalCol, 0.0, 1.0), float3(1.0 / 2.2));
      }

      amzOutput = float4(finalCol, src.a);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
